prepareChapters.set:
${
  {
    series: .seriesPage.props.series,
    autoUpdate: .autoUpdate,
    autoUpdateExplicit: .autoUpdateExplicit,
    lastDownloaded: .lastDownloaded,
    novelUrl: .novelUrl,
    novelSlug: .novelSlug,
    chapterFrom: .chapterFrom,
    chapterTo: .chapterTo,
    chapters: (
      .chaptersResponse.chapters
      | map(select(.is_premium != true))
      | reverse
      | map(. + {
          chapterNumber: ((.number // .chapter_number // (.name | split(" ") | last)) | tonumber)
        })
      | map(select(.chapterNumber >= $input.chapterFrom and .chapterNumber <= $input.chapterTo))
    ),
    downloaded: []
  }
}

