findChapterLinks.set:
${ . + {
  chapterLinks:(.seriesHtml | split("href=\"") | map(split("\"") | .[0]) | map(select(startswith("/") and (ascii_downcase|contains("chapter"))))),
  absoluteChapterLinks:(.seriesHtml | split("href=\"") | map(split("\"") | .[0]) | map(select(startswith("http") and (ascii_downcase|contains("chapter")))))
} }
